<?php
require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM classes WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$action=$_POST['action']??'';if($action==='class'){ $id=(int)($_POST['id']??0);$d=[trim($_POST['name']),$_POST['status']];if($id){$pdo->prepare("UPDATE classes SET name=?,status=? WHERE id=?")->execute([...$d,$id]);audit($pdo,'update','Updated class #'.$id);go('classes.php','Class updated successfully');}$pdo->prepare("INSERT INTO classes(name,status) VALUES(?,?)")->execute($d);audit($pdo,'create','Created class');go('classes.php','Class added successfully');}}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("UPDATE classes SET status='Inactive' WHERE id=?")->execute([$id]);audit($pdo,'delete','Deactivated class #'.$id);go('classes.php','Class deactivated');}
$rows=$pdo->query("SELECT c.*,COUNT(d.id) division_count FROM classes c LEFT JOIN divisions d ON d.class_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();
admin_layout('Classes & Divisions','Manage classes and see how many divisions are configured.');echo '<div class="actions"><button class="btn" data-modal="classModal">＋ Add Class</button><a class="btn secondary" href="divisions.php">Manage Divisions</a></div></div>';flash();
echo '<div class="card"><div class="toolbar"><input class="search" data-search="#classTable" placeholder="Search class"><span class="muted">'.count($rows).' classes</span></div><div class="table-wrap"><table class="table" id="classTable"><thead><tr><th>Class</th><th>Divisions</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td><b>'.e($r['name']).'</b></td><td>'.e((string)$r['division_count']).'</td><td><span class="badge '.($r['status']==='Active'?'success':'danger').'">'.e($r['status']).'</span></td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Deactivate this class?" href="?delete='.$r['id'].'">Deactivate</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="classModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Class':'Add Class').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="class"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>Class Name<input name="name" required value="'.e($edit['name']??'').'"></label><label>Status<select name="status"><option>Active</option><option'.(($edit['status']??'')==='Inactive'?' selected':'').'>Inactive</option></select></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Class':'Save Class').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("classModal").classList.add("show")</script>';admin_end();